import {
  Container,
  Typography,
  Card,
  CardMedia,
  CircularProgress,
  Chip,
  Box,
  Button,
} from "@mui/material";

import { useParams, Link, useNavigate } from "react-router-dom";

import { useEffect, useState } from "react";

import API from "../services/api";

import axios from "axios";

export default function BlogDetails() {
  const { id } = useParams();

  const [blog, setBlog] = useState(null);
  const [loading, setLoading] = useState(true);

  const navigate = useNavigate();
  const user = JSON.parse(
  localStorage.getItem("user")
);

  const handleDelete = async () => {

    const confirmDelete = window.confirm(
      "Are you sure you want to delete this blog?"
    );

    if (!confirmDelete) return;

    try {

      const token = localStorage.getItem(
        "token"
      );

      await axios.delete(
        `http://localhost:5000/api/blogs/${id}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      alert("Blog deleted successfully");

      navigate("/");

    } catch (error) {

      console.log(error);

      alert("Failed to delete blog");
    }
  };

  useEffect(() => {
    const fetchBlog = async () => {
      try {
        const response = await API.get(
          `/blogs/${id}`
        );

        setBlog(response.data);
      }
      catch (error) {
        console.log(error);
      }
      finally {
        setLoading(false);
      }
    };

    fetchBlog();
  }, [id]);

  if (loading) {
    return (
      <Container sx={{ py: 5 }}>
        <CircularProgress />
      </Container>
    );
  }

  if (!blog) {
    return (
      <Container sx={{ py: 5 }}>
        <Typography>
          Blog not found!
        </Typography>
      </Container>
    );
  }
  return (
    <Container maxWidth="md" sx={{ py: 5 }}>

      <Card
        sx={{
          borderRadius: 4,
          overflow: "hidden",
        }}
      >

        <CardMedia
          component="img"
          height="400"
          image={blog.image}
          alt={blog.title}
        />

        <Box sx={{ p: 4 }}>

          <Chip
            label={blog.category}
            color="primary"
            sx={{ mb: 2 }}
          />

          <Typography
            variant="h3"
            fontWeight={700}
            gutterBottom
          >
            {blog.title}
          </Typography>

          <Typography
            variant="body1"
            color="text.secondary"
            sx={{
              lineHeight: 2,
              mt: 3,
            }}
          >
            {blog.content}
          </Typography>
          <Button
            component={Link}
            to={`/edit-blog/${blog._id}`}
            variant="contained"
            sx={{ mt: 3 }}
          >
            Edit Blog
          </Button>
          <Button
            variant="outlined"
            color="error"
            sx={{ mt: 2, ml: 2 }}
            onClick={handleDelete}
          >
            Delete Blog
          </Button>
        </Box>

      </Card>

    </Container>
  );
}
